G=load()

def solve(A, strict=True):
    H,W=A.shape
    vals=Counter(A.flat); bg=vals.most_common(1)[0][0]
    order=[v for v,_ in vals.most_common()]; L=order[1]
    if strict:
        R=[i for i in range(H) if sum(1 for j in range(W) if A[i,j]==L)>=W*0.6 and any(A[i,j]!=L for j in range(W))]
        C=[j for j in range(W) if sum(1 for i in range(H) if A[i,j]==L)>=H*0.6 and any(A[i,j]!=L for i in range(H))]
    else:
        R=[i for i in range(H) if sum(1 for j in range(W) if A[i,j]==L)>=W*0.6]
        C=[j for j in range(W) if sum(1 for i in range(H) if A[i,j]==L)>=H*0.6]
    out=np.full((len(R)-1,len(C)-1),bg,int)
    for i in range(len(R)-1):
        for j in range(len(C)-1):
            cs={int(A[R[a],C[b]]) for a in (i,i+1) for b in (j,j+1)}
            if len(cs)==1: out[i,j]=cs.pop()
    return out

